mapper.select:
select r.riskid,r.risknumber,r.riskname,o.orgname as unit,r.riskcreatedt,r.version -- from TBL_RISK r left join TBL_ORGANIZATION o on r.unit = to_char(o.orgid) from TBL_RISK r left join TBL_ORGANIZATION o on r.unit = o.orgid
1=1 -- r.RISKID in (select max(RISKID) from TBL_RISK group by RISKNUMBER)
${sql}
and ${ew.sqlSegment}

select  TBL_INNERRULE.innrulid,RULENUMBER,RULENAME,ORGNAME,PUBLISHDATE
from TBL_INNERRULE TBL_INNERRULE LEFT JOIN TBL_ORGANIZATION org on TBL_INNERRULE.PUBLISHORG=TO_CHAR(ORG.ORGID)

    TBL_INNERRULE.innrulid in (select TBL_RISK_INNERRULE.innrulid from TBL_RISK_INNERRULE where TBL_RISK_INNERRULE.riskid = #{param1}) and
    ${ew.sqlSegment}

select *
from TBL_INNERRULE where innrulid in (select innrulid from TBL_RISK_INNERRULE where riskid = #{riskid})
 and  ${ew.sqlSegment}

select OUTRULID,RULENUMBER,RULENAME,ORGNAME,PUBLISHDATE
from tbl_outerrule LEFT JOIN TBL_ORGANIZATION ORG on tbl_outerrule.PUBLISHORG=TO_CHAR(ORG.ORGID)
where outrulid in (select outrulid from TBL_RISK_OUTERRULE where riskid =#{param1})
and ${ew.sqlSegment}

select OUTRULID, RULENUMBER, RULENAME, PUBLISHORG, PUBLISHDATE, TAKEEFFECTTIME
from TBL_OUTERRULE t where  (createorgid = #{orgid} OR ISPYTHONFLAG = 1)
and ${ew.sqlSegment}

select R2.SIZE,r.*, s.realname as staffname,cat.riskcatname as riskcatidname,o.orgname as unitname,d.ORGNAME as linkDeptName from ( select case when max(rar.RISKLEVEL) is NULL then '0' else max(rar.RISKLEVEL) END as size,r.riskid from tbl_risk r left join TBL_RISK_ASSPLAN_RISK rar on rar.RISKID = r.RISKID group by r.riskid ) r2 left join tbl_risk r on r.riskid=r2.RISKID left join tbl_organization o on r.unit = o.orgid left join tbl_organization d on r.LINKDEPTID = d.ORGID left join TBL_RISKCATEGORY cat on cat.riskcatid=r.riskcatid left join tbl_staff s on s.staffid=r.staffid where 1=1 and
r.riskcatid in (${ids})
${sql}
and ${ew.sqlSegment}

SELECT COUNT(1) FROM TBL_RISK WHERE 1=1

	and RISKLEVEL =#{type}


	AND UNIT=#{orgid}


	AND year(riskcreatedt)=#{year}

	 select org.orgname as zrbmName,o.orgname as unitname,trc.riskcopingid,d.ORGNAME as linkDeptName,
	 s.realname as staffname,cat.riskcatname as riskcatidname,r.* from tbl_risk r  
	             left join tbl_organization o on r.unit = to_char(o.orgid) 
	              left join tbl_organization d on r.linkdeptid=d.orgid
	             left join tbl_organization org on org.orgid=r.BELONGSTO
	             left join TBL_RISK_COPING trc on trc.riskid = r.riskid  
	             left join tbl_staff s on s.staffid=r.staffid
	             left join TBL_RISKCATEGORY  cat on cat.riskcatid=r.riskcatid
	             where  1=1

		  and  r.riskid   in (select max(riskid) as riskcreatedt from tbl_risk where riskcatid in  

		     #{item}

		     group by riskid) 



	    and risknumber  LIKE
				concat(concat('%',#{queryParam.risknumber}),'%')



	    and riskname  LIKE
				concat(concat('%',#{queryParam.riskname}),'%')



	    and cat.riskcatname  LIKE
				concat(concat('%',#{queryParam.riskcatidname}),'%')


	    and  d.orgname LIKE
				concat(concat('%',#{queryParam.linkDeptName}),'%')



	     and  r.linkDeptId in

	      #{item}	   



	     and  r.unit in

	      #{item}	   




	    and r.riskcatname  LIKE
				concat(concat('%',#{queryParam.riskcatname}),'%')



	    and r.unit =#{queryParam.unit}


	    and  r.linkDeptId =#{queryParam.linkDeptId}


		    and (trc.status is NULL or trc.STATUS=0)


	    and trc.status=#{queryParam.status}


	    and level  not in ('未评估')


	    and (select RISKLEVEL from TBL_RISK_ASSPLAN_RISK 
       where RISKID=r.riskid AND ASSDATE = (SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = r.riskid)) is null


	    and (select RISKLEVEL from TBL_RISK_ASSPLAN_RISK 


		where RISKID=r.riskid AND ASSDATE = (SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = r.riskid)) in

			#{item}



		where RISKID=r.riskid AND ASSDATE = (SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = r.riskid))=#{queryParam.cxlevel}









		and riskcreatedt >=#{queryParam.startdate}


		and riskcreatedt <=#{queryParam.enddate}


	   and r.riskid in ( select a.riskid  from TBL_RISK_ASSPLAN_RISK a  left join tbl_risk s on s.riskid=a.riskid   where a.assdate=(SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = a.riskid) 
    	 	 )


	   and r.riskid in ( select a.riskid  from TBL_RISK_ASSPLAN_RISK a  left join tbl_risk s on s.riskid=a.riskid   where a.assdate=(SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = a.riskid) 
    		 )


	    	  and r.riskid in ( SELECT distinct t2.riskid   from TBL_RISK_ASSPLAN_RISK t2 left join TBL_RISK_ASSPLAN p on p.assplanid=t2.assplanid
               left join tbl_risk r1 on r1.RISKID=t2.RISKID where p.unit is not null 

	              and r1.unit=#{queryParam.unit}


	              and  r1.linkDeptId =#{queryParam.linkDeptId}


	              and  r1.linkDeptId in

	                       #{item}	   



	               and  r1.unit in

	             #{item}	   



              and planstatus =2
             AND NOT EXISTS (
               SELECT 1   FROM TBL_RISK_ASSPLAN_RISK  t3  left join TBL_RISK_ASSPLAN p on p.assplanid=t3.assplanid
                 WHERE t3.riskid = t2.riskid  AND p.planstatus =3
))


	     and (select RISKLEVEL from TBL_RISK_ASSPLAN_RISK 
       where RISKID=r.riskid AND ASSDATE = (SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = r.riskid)) is null


	      and  ( r.riskstatus !=0 or r.riskstatus is null) 


	      and   r.riskstatus =0



	         and org.orgname =#{queryParam.belongsto}

	 ${sql} 
	order by RISKCREATEDT desc

select distinct org.orgname as zrbmName,o.orgname as unitname,trc.riskcopingid,d.ORGNAME as linkDeptName, s.realname as staffname,cat.riskcatname as riskcatidname,r.* from tbl_risk r left join tbl_organization o on r.unit = to_char(o.orgid) left join tbl_organization d on r.linkdeptid=d.orgid left join tbl_organization org on org.orgid=r.BELONGSTO left join TBL_RISK_COPING trc on trc.riskid = r.riskid left join tbl_staff s on s.staffid=r.staffid left join TBL_RISKCATEGORY cat on cat.riskcatid=r.riskcatid where 1=1 and r.unit is not null
and r.riskid in (select max(riskid) as riskcreatedt from tbl_risk where riskcatid in
#{item}
group by riskid)
and org.orgname LIKE concat(concat('%',#{queryParam.linkDeptName}),'%')
and riskname = #{queryParam.riskname}
and cat.riskcatname =#{queryParam.riskcatidname}
and (select RISKLEVEL from TBL_RISK_ASSPLAN_RISK where RISKID=r.riskid AND ASSDATE = (SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = r.riskid))=#{queryParam.cxlevel}
and r.riskcatname LIKE concat(concat('%',#{queryParam.riskcatname}),'%')
and r.unit =#{queryParam.unit}
and r.riskid in ( select a.riskid from TBL_RISK_ASSPLAN_RISK a left join tbl_risk s on s.riskid=a.riskid where a.assdate=(SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = a.riskid) and ( s.riskstatus !=0 or s.riskstatus is null))
and r.riskid in ( select a.riskid from TBL_RISK_ASSPLAN_RISK a left join tbl_risk s on s.riskid=a.riskid where a.assdate=(SELECT MAX(ASSDATE) FROM TBL_RISK_ASSPLAN_RISK WHERE RISKID = a.riskid) and s.riskstatus =0)
${sql} order by RISKCREATEDT desc

select riskcatname as name,count(1) as number from tbl_risk  r

and r.unit=#{company}

group by riskcatname

select count(1) as number from tbl_risk where ( status!=6 or status is
null )

	and unit=#{company}

select o.orgname as name,count(1) as number from tbl_risk r left join tbl_organization o on o.orgid=r.unit where 1=1
AND year(riskcreatedt)=#{year}
group by o.orgname
